@page "/"

<PageTitle>ShipmentTracker - Home</PageTitle>

<h1>Welcome to ShipmentTracker</h1>
<p class="lead">Track your shipments in real-time, anywhere in the world.</p>

<div class="row mt-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Track a Shipment</h5>
                <p class="card-text">Enter your tracking number to see the current status and estimated delivery.</p>
                <div class="input-group">
                    <input type="text" class="form-control" placeholder="Enter tracking number"
                           @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
                    <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
                </div>
                @if (searchResult is not null)
                {
                    <div class="mt-3 alert alert-info">
                        <strong>@searchResult.TrackingNumber</strong><br />
                        Status: <span class="badge bg-secondary">@searchResult.Status</span><br />
                        Destination: @searchResult.Destination<br />
                        @if (searchResult.EstimatedDelivery.HasValue)
                        {
                            <span>Estimated Delivery: @searchResult.EstimatedDelivery.Value.ToString("MMM dd, yyyy")</span>
                        }
                    </div>
                }
                @if (searchError is not null)
                {
                    <div class="mt-3 alert alert-warning">@searchError</div>
                }
            </div>
        </div>
    </div>
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">For Dispatchers</h5>
                <p class="card-text">Manage all shipments, update statuses, and create new shipments.</p>
                <a href="dispatcher" class="btn btn-outline-primary">Go to Dispatch Dashboard</a>
            </div>
        </div>
        <div class="card mt-3">
            <div class="card-body">
                <h5 class="card-title">For Customers</h5>
                <p class="card-text">View all your shipments and their delivery estimates.</p>
                <a href="my-shipments" class="btn btn-outline-primary">View My Shipments</a>
            </div>
        </div>
    </div>
</div>

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private string trackingNumber = string.Empty;
    private ShipmentDto? searchResult;
    private string? searchError;

    private async Task TrackShipment()
    {
        searchResult = null;
        searchError = null;

        if (string.IsNullOrWhiteSpace(trackingNumber))
        {
            searchError = "Please enter a tracking number.";
            return;
