@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private List<ShipmentDto>? shipments;
    private string filterText = string.Empty;
    private bool showCreateForm;
    private string newOrigin = string.Empty;
    private string newDestination = string.Empty;
    private DateTime? newEstimatedDelivery;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments?.Where(s =>
            string.IsNullOrWhiteSpace(filterText) ||
            s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ShowCreateForm() => showCreateForm = true;
    private void CancelCreate()
    {
        showCreateForm = false;
        newOrigin = string.Empty;
        newDestination = string.Empty;
        newEstimatedDelivery = null;
    }

    private async Task CreateShipment()
    {
        if (string.IsNullOrWhiteSpace(newOrigin) || string.IsNullOrWhiteSpace(newDestination))
            return;

        var created = await ShipmentService.CreateShipmentAsync(new CreateShipmentRequest
        {
            Origin = newOrigin,
            Destination = newDestination,
            EstimatedDelivery = newEstimatedDelivery
        });

        shipments?.Insert(0, created);
        CancelCreate();
    }

